"use client";

import { useState, useEffect, useRef } from "react";
import { X, Send, Loader2, MessageSquare, Package, MapPin, ExternalLink } from "lucide-react";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card } from "./ui/card";
import { useAuth } from "@/app/context/AuthContext";
import { getConversations, getMessages, sendChatMessage } from "@/app/lib/api";
import { resolvePhotoUrl } from "@/app/lib/image-utils";
import Image from "next/image";
import { io, Socket } from "socket.io-client";
import { toast } from "sonner";

interface DirectChatModalProps {
    isOpen: boolean;
    onClose: () => void;
    sellerId: string;
    itemId: string;
    productData: {
        title: string;
        price: number;
        images: string[];
    };
}

export default function DirectChatModal({ isOpen, onClose, sellerId, itemId, productData }: DirectChatModalProps) {
    const { user } = useAuth();
    const [messages, setMessages] = useState<any[]>([]);
    const [input, setInput] = useState("");
    const [loading, setLoading] = useState(false);
    const [sending, setSending] = useState(false);
    const [conversationId, setConversationId] = useState<string | null>(null);
    const socketRef = useRef<Socket | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    // Initial fetch and Socket setup
    useEffect(() => {
        if (isOpen && user && sellerId && itemId) {
            fetchConversationAndMessages();

            const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";
            const socketUrl = apiUrl.replace(/\/api\/?$/, "");

            socketRef.current = io(socketUrl, {
                withCredentials: true
            });

            socketRef.current.on("connect", () => {
                socketRef.current?.emit("joinUserRoom", user._id);
            });

            socketRef.current.on("newMessage", (data: any) => {
                if (data.itemId === itemId && (data.message.sender === sellerId || data.message.sender._id === sellerId)) {
                    setMessages(prev => {
                        if (prev.find(m => m._id === data.message._id)) return prev;
                        return [...prev, data.message];
                    });
                }
            });

            return () => {
                socketRef.current?.disconnect();
            };
        }
    }, [isOpen, user, sellerId, itemId]);

    const fetchConversationAndMessages = async () => {
        setLoading(true);
        try {
            // First, try to find an existing conversation
            const convRes: any = await getConversations();
            if (convRes.success) {
                const existingConv = convRes.data.find((c: any) => 
                    c.item?._id === itemId && 
                    c.participants.some((p: any) => p._id === sellerId)
                );

                if (existingConv) {
                    setConversationId(existingConv._id);
                    const msgRes: any = await getMessages(existingConv._id);
                    if (msgRes.success) {
                        setMessages(msgRes.data);
                    }
                }
            }
        } catch (error) {
            console.error("Failed to fetch messages", error);
        } finally {
            setLoading(false);
        }
    };

    const handleSend = async (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!input.trim() || sending) return;

        const text = input.trim();
        setInput("");
        setSending(true);

        try {
            const res: any = await sendChatMessage(sellerId, itemId, text);
            setMessages(prev => [...prev, res.data]);
            if (!conversationId) setConversationId(res.data.conversationId);
        } catch (error) {
            toast.error("Failed to send message");
            setInput(text);
        } finally {
            setSending(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[110] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300">
            <Card className="w-full sm:max-w-md h-[80vh] sm:h-[600px] flex flex-col shadow-2xl rounded-t-3xl sm:rounded-3xl overflow-hidden animate-in slide-in-from-bottom-10 duration-500">
                {/* Header */}
                <div className="p-4 border-b bg-primary text-primary-foreground flex items-center justify-between shadow-md">
                    <div className="flex items-center gap-3">
                        <div className="relative h-10 w-10 rounded-lg overflow-hidden bg-white/20 border border-white/10">
                            {productData.images?.[0] && (
                                <Image
                                    src={resolvePhotoUrl(productData.images[0]) || "/placeholder.png"}
                                    alt="item"
                                    fill
                                    className="object-cover"
                                />
                            )}
                        </div>
                        <div className="flex flex-col">
                            <h3 className="font-bold text-sm truncate max-w-[180px]">{productData.title}</h3>
                            <span className="text-[10px] opacity-80 font-medium">Chatting with Seller</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-1">
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-white hover:bg-white/10 rounded-full"
                            onClick={() => window.location.href = "/messages"}
                            title="Open in Full Page"
                        >
                            <ExternalLink size={16} />
                        </Button>
                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-white hover:bg-white/10 rounded-full"
                            onClick={onClose}
                        >
                            <X size={18} />
                        </Button>
                    </div>
                </div>

                {/* Messages */}
                <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-muted/5 scrollbar-thin">
                    {loading ? (
                        <div className="h-full flex items-center justify-center">
                            <Loader2 className="h-6 w-6 animate-spin text-primary opacity-20" />
                        </div>
                    ) : messages.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-center p-6 space-y-3 opacity-30">
                            <MessageSquare size={48} className="text-primary/20" />
                            <p className="text-xs font-bold uppercase tracking-widest">Starting Conversation</p>
                        </div>
                    ) : (
                        messages.map((msg, idx) => {
                            const isMe = msg.sender === user?._id || msg.sender?._id === user?._id;
                            return (
                                <div key={idx} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[80%] p-3 rounded-2xl text-sm shadow-sm ${
                                        isMe 
                                        ? 'bg-primary text-primary-foreground rounded-br-none' 
                                        : 'bg-background border text-foreground rounded-bl-none'
                                    }`}>
                                        <p className="leading-relaxed">{msg.text}</p>
                                        <span className={`text-[9px] mt-1 block opacity-60 ${isMe ? 'text-right' : 'text-left'}`}>
                                            {new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                    </div>
                                </div>
                            );
                        })
                    )}
                    <div ref={messagesEndRef} />
                </div>

                {/* Footer Input */}
                <div className="p-4 border-t bg-background">
                    <form onSubmit={handleSend} className="flex gap-2">
                        <Input
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Type a message..."
                            className="rounded-full bg-muted/50 border-none focus-visible:ring-1"
                        />
                        <Button 
                            type="submit" 
                            size="icon" 
                            disabled={!input.trim() || sending}
                            className="rounded-full h-10 w-10 shrink-0 shadow-lg"
                        >
                            {sending ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
                        </Button>
                    </form>
                </div>
            </Card>
        </div>
    );
}
